'use client';
import { useFocusFinders, useFocusedElementChange } from "@fluentui/react-tabster";
import { useTreeNavigationBase } from "./useTreeNavigationBase.js";
/***
 * Hook used to manage navigation in the tree.
 *
 * @param navigationMode - the navigation mode of the tree, 'tree' (default) or 'treegrid'
 */ export function useTreeNavigation(navigationMode = 'tree') {
    const { findFirstFocusable } = useFocusFinders();
    return useTreeNavigationBase(navigationMode, {
        findFirstFocusable,
        useFocusedElementChange
    });
}
